steps.script:
function transform(ctx) {
  var full = ctx.username.trim();
  if (!full) throw new Error("校园网账号不能为空");
  var timestamp = String(Math.floor(now_ms()));
  return { full_username: full, encoded_username: url_encode(full), callback: "jQuery" + timestamp + "0000_" + timestamp, ts: timestamp };
}

function transform(ctx) {
  var acId = "2";
  var n = "200";
  var type = "1";
  var ip = ctx.local_ip;
  if (!ip) throw new Error("无法获取本机 IP，请确认已连接校园网");
  var token = ctx.vars.challenge;
  if (!token) throw new Error("认证服务器没有返回 challenge");
  var full = ctx.vars.full_username;
  var info = srun_info(JSON.stringify({ username: full, password: ctx.password, ip: ip, acid: acId, enc_ver: "srun_bx1" }), token);
  var hmd5 = hmac_md5(token, ctx.password);
  var checksum = sha1(token + full + token + hmd5 + token + acId + token + ip + token + n + token + type + token + info);
  var timestamp = String(Math.floor(now_ms()));
  return { encoded_username: url_encode(full), encoded_password: url_encode("{MD5}" + hmd5), encoded_info: url_encode(info), checksum: checksum, ac_id: acId, n: n, protocol_type: type, login_ip: ip, login_callback: "jQuery" + timestamp + "0000_" + timestamp, login_ts: timestamp };
}
